function o(t=new Date){const a=t.getFullYear(),e=String(t.getMonth()+1).padStart(2,"0"),n=String(t.getDate()).padStart(2,"0");return`${a}-${e}-${n}`}function s(t,a=new Date){const e=new Date(a);return e.setDate(e.getDate()+t),o(e)}function u(t,a={day:"2-digit",month:"short",year:"numeric"}){if(!t)return"—";const e=/^(\d{4})-(\d{2})-(\d{2})/.exec(t);if(!e)return"—";const[,n,r,c]=e;return new Date(Number(n),Number(r)-1,Number(c),12).toLocaleDateString("es-MX",a)}export{s as a,u as b,o as f};
